esbmc_test_source:
contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _value) public payable {
        require(true);

        // Record before-state observable through public surface
        address beforeOwner = c.owner(); if (__ESBMC_reverted()) return;
        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBalance = address(c).balance;

        // Make the test contract non-owner by changing owner through a public entry? No direct setter exists.
        // Instead, ensure the caller is not the owner by calling from a different address is impossible in this harness.
        // The only way to be non-owner is to transfer ownership, which isn't available. So we must drive a call that is not from owner.
        // A trick: the test contract can call withdrawAll to change state, but ownership remains.
        // Since no ownership transfer exists, a non-owner call cannot be constructed in this harness. Therefore, the rule about non-owner is not reachable.
        // To keep the rule meaningful and reachable, we instead assert about the owner case but a different rule: value transfer caps at balance and only owner can withdraw.
        // However, the focus asks for whether withdraw reverts on inputs. For owner, it never reverts if balance sufficient; otherwise reverts.
        // We'll write a rule about the owner's withdraw call and the balance change.

        // Since we are the owner, attempt withdraw with _value.
        bool reverted;
        uint balanceBefore = address(c).balance;
        c.withdraw(_value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // After state
        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBalance = address(c).balance;

        // General rule: For a withdraw call by the owner with value v,
        // if it succeeds, then the contract's balance decreases by exactly v and depositsCount and owner are unchanged;
        // if it reverts, then the contract's balance, depositsCount, and owner are unchanged.
        // Also, if v > balanceBefore, it must revert.
        // We can encode this as a single assert over reverted, _value, balanceBefore, afterBalance, beforeCount, afterCount, beforeOwner, afterOwner.

        address afterOwner = c.owner(); if (__ESBMC_reverted()) return;

        assert(
            (reverted && afterBalance == balanceBefore && afterCount == beforeCount && afterOwner == beforeOwner)
            ||
            (!reverted && afterBalance + _value == balanceBefore && afterCount == beforeCount && afterOwner == beforeOwner)
        );
    }

    receive() external payable {}
}

