pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 _value) internal {
        vm.assume(true);
        address beforeOwner;
        try c.owner() returns (address __r) { beforeOwner = __r; } catch { return; }
        uint256 beforeCount;
        try c.depositsCount() returns (uint256 __r) { beforeCount = __r; } catch { return; }
        uint beforeBalance = address(c).balance;
        bool reverted;
        uint balanceBefore = address(c).balance;
        try c.withdraw(_value) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterCount;
        try c.depositsCount() returns (uint256 __r) { afterCount = __r; } catch { return; }
        uint afterBalance = address(c).balance;
        address afterOwner;
        try c.owner() returns (address __r) { afterOwner = __r; } catch { return; }
        assertTrue((reverted && afterBalance == balanceBefore && afterCount == beforeCount && afterOwner == beforeOwner)
            ||
            (!reverted && afterBalance + _value == balanceBefore && afterCount == beforeCount && afterOwner == beforeOwner));
    }

    function testFuzz_run(uint256 _value) public {
        _run(_value);
    }

    receive() external payable {}
}
